from pathlib import Path
import json,hashlib,shutil,subprocess
root=Path.cwd();private=root/'.local/step07/fix-round4';stage=private/'final';out=root/'docs/evidence/step-07/fix-round4';source='59423201ba10ee71c3d1b04cebec69659017b7c7'
assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==source
out.mkdir(parents=True,exist_ok=False);provenance=[]
def sha(b):return hashlib.sha256(b).hexdigest()
def sanitize(t):
 return t.replace(str(root),'<CODING_WORKTREE>').replace('<LOCAL_PINNED_NATIVE_CORE>','<LOCAL_PINNED_NATIVE_CORE>').replace('<EXISTING_NODE_22_21_1_BIN>','<EXISTING_NODE_22_21_1_BIN>')
def save(dst,value):
 p=out/dst;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def capture(src,dst,kind=None,exact=False):
 target=out/dst;target.parent.mkdir(parents=True,exist_ok=True);raw=src.read_bytes()
 try:original=str(src.relative_to(root))
 except ValueError:original=str(src)
 if kind=='log' or src.suffix in ['.log','.py','.mjs']:
  if target.suffix!='.json':target=target.with_name(target.name+'.json')
  target.write_text(json.dumps({'privateOriginal':original,'originalSHA256':sha(raw),'originalBytes':len(raw),'sanitized':True,'text':sanitize(src.read_text())},ensure_ascii=False,indent=2)+'\n')
 elif src.suffix=='.json' and not exact:target.write_text(sanitize(src.read_text()))
 else:shutil.copyfile(src,target)
 provenance.append({'privateOriginal':original,'originalSHA256':sha(raw),'originalBytes':len(raw),'evidenceCopy':str(target.relative_to(out)),'evidenceSHA256':sha(target.read_bytes()),'evidenceBytes':target.stat().st_size,'sanitized':not exact and src.suffix in ['.log','.json','.py','.mjs']})
for p in sorted(stage.iterdir()):
 if not p.is_file() or p.name=='regression06-private.json' or p.suffix=='.png':continue
 if p.suffix=='.jsonl':
  save('results/commands.json',{'sourceSHA':source,'records':[json.loads(x) for x in p.read_text().splitlines()],'originalSHA256':sha(p.read_bytes()),'originalBytes':p.stat().st_size})
  provenance.append({'privateOriginal':str(p.relative_to(root)),'originalSHA256':sha(p.read_bytes()),'originalBytes':p.stat().st_size,'evidenceCopy':'results/commands.json','representation':'JSON array of exact JSONL records'})
 elif p.suffix=='.log':capture(p,Path('results')/(p.name+'.json'),kind='log')
 elif p.suffix=='.json':capture(p,Path('results')/p.name)
for directory in ['browser-production','browser-dev','restored-browser','restored-browser-complete']:
 for p in sorted((stage/directory).rglob('*')):
  if p.is_file() and p.suffix in ['.json','.png','.zip']:capture(p,Path(directory)/p.relative_to(stage/directory),exact=p.suffix in ['.png','.zip'])
if (stage/'retained-runtime.png').exists():capture(stage/'retained-runtime.png',Path('retained-runtime.png'),exact=True)
owners=[]
for p in (root/'.local/step07/tests').glob('*/ownership.json'):
 j=json.loads(p.read_text())
 if j['sourceContext']['commit']==source:owners.append(p.parent)
assert len(owners)==1,owners
for p in sorted(owners[0].glob('*.json')):capture(p,Path('http-and-recovery')/p.name)
manifest=next(root.glob('artifacts/step07-59423201*/manifest.json'));capture(manifest,Path('engineering-manifest.json'),exact=True)
# Verify the original R4 files, preserve its conclusion and errors.
original=private/'independent-round4-original';ledger=original/'evidence/ledger.json';j=json.loads(ledger.read_text());audit=[]
