save('original-round4.json',{'reportText':report.decode(),'reportSHA256':sha(report),'reportBytes':len(report),'originalLedgerSHA256':sha(ledger.read_bytes()),'payloadsVerified':430,'originalMainReport':'/Users/dingshinn/Desktop/rpg-maker-maker/docs/evidence/step-07/independent-round4/report.md','audit':audit,'originalConclusion':'REQUIRES_REVISION','counterexampleExit0':'Captured original defects, not candidate PASS','originalsModified':False})
for name in ['duplicate-publication.json','duplicate-publication-legacy.json','state-skew/evidence.json','project-list-race/evidence.json','project-list-race-dev/evidence.json','execution-notes.json']:
 capture(original/'evidence'/name,Path('original-probes')/name)
for name in ['duplicate-publication.mjs.txt','duplicate-publication-legacy.mjs.txt','state-skew.mjs.txt','project-list-race.mjs.txt','project-list-race-dev.mjs.txt']:
 capture(original/'evidence/probes'/name,Path('original-probes')/(name+'.json'),kind='log')
for p in sorted(private.glob('*.log')):capture(p,Path('pre-freeze')/(p.name+'.json'),kind='log')
for p in sorted(private.glob('*.json')):capture(p,Path('author-checkpoint')/p.name)
for d in ['old-ef30-list-failure-results','pre-freeze-final-browser-output','pre-freeze-final-test-results','pre-freeze-list-cancel-init-failure','pre-freeze-list-first-evidence']:
 for p in sorted((private/d).rglob('*')):
  if p.is_file() and p.suffix in ['.json','.png'] and 'private' not in p.relative_to(private/d).parts:
   capture(p,Path('superseded-and-failures')/d/p.relative_to(private/d),exact=p.suffix=='.png')
for p in sorted(private.iterdir()):
 if p.is_file() and p.suffix in ['.py','.mjs']:capture(p,Path('author-probes')/(p.name+'.json'))
capture(root/'.local/step07/scalars-original.mjs',Path('author-probes/scalars-original.mjs.json'))
for p in sorted((private/'independent-reference/evidence').rglob('*')):
 if p.is_file() and p.suffix in ['.json','.png','.zip','.md']:
  capture(p,Path('independent-reference')/p.relative_to(private/'independent-reference/evidence'),exact=p.suffix in ['.png','.zip','.md'])
for p in sorted((private/'reference-probes').glob('*')):
 if p.is_file():capture(p,Path('reference-probes')/(p.name+'.json'))
for p in sorted(owners[0].glob('*.png')):capture(p,Path('http-and-recovery')/p.name,exact=True)
recovery=json.loads((stage/'broken-recovery-clone.json').read_text());capture(Path(recovery['clone']['assets']).parent/'recovered-standard.zip',Path('recovered-counterexample-standard.zip'),exact=True)
privateInventory=[]
for p in sorted(private.rglob('*')):
 if p.is_file() and not p.is_relative_to(private/'regression06') and not p.is_relative_to(private/'private') and p.suffix in ['.log','.json','.jsonl','.mjs','.py','.zip','.png']:
  privateInventory.append({'path':str(p.relative_to(root)),'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size,'scope':'Original retained private; credentials/DB/dump/assets never copied'})
save('retained-private-inventory.json',{'sourceSHA':source,'files':privateInventory})
save('original-file-provenance.json',{'sourceSHA':source,'files':provenance})
save('configuration.json',{'role':'step_coder','model':'gpt-6.1-sol','reasoningEffort':'xhigh','serviceTier':'default','clientStandard':'default','clientEvidence':'author-checkpoint/client-configuration.json','serverFinalFields':'UNVERIFIED_NOT_EXPOSED','sameCID':'01a132c0-f44b-75f0-bea5-7f4e5e77a6ea','normalRecoveryAttempts':3,'formalReviewsUsed':4,'nextFormalReview':5,'reviewLimit':None,'authorization':'2026-10-14 removes mechanical limit; history not reset; verified progress required','collaborationCalls':False,'globalConfigChanged':False,'independentReview':'NOT_EXECUTED_BY_CODER','CI':'NOT_EXECUTED_BY_CODER','release':'NOT_EXECUTED_BY_CODER','artifactMZ':'NOT_EXECUTED','userArtConfirmation':'NOT_EXECUTED','realProviderSDKKeyPromptCalls':'NOT_EXECUTED','step08_09_10':'NOT_STARTED'})
save('execution-notes.json',{'sourceSHA':source,'originalReviewerResult':'REQUIRES_REVISION round4; R3 findings closed by R4 Reviewer in original scope; R1/R2 closed previously','baseline':'New correct assertions fail on ef30 for missing FinalExport, mixed metadata, lost initial list; original 430 evidence, all failures, probes, traces and fixture DBs retained. Counterexample exit0 is not PASS.','preFreeze':'First boundary probe placed the prepare arm late and timed out; corrected real COMMIT fence catches original metadata defect. Type/API probe mistakes, old own API port collision, about:blank storage init error and production API with dev client 403 all retained. Tests adjusted their deployment/assumptions, no server budget relaxed. Both real clients pass first/replacement/history-only after proper production/development API deployment.','latest':'Only exact594 bound final results claimed. Old and pre-freeze failures/control results not substituted for latest candidate. Original5s/60s budgets retained.','privateSnapshot':'Fixed snapshot after adapters complete; later progress and commit receipts separate. Historical R2 collector drift and R3 partial collector retained in historical reports.','resourceRecovery':'Initial read-only audit of own72 DBs found zero existing affected jobs before counterexample fixtures. Own synthetic failing ef30 fixture backed up and restored to fresh empty own DB/root, protected conversion verified only on clone; original failure preserved; no batch mutation/reset.','scope':'No cases removed, thresholds lowered, fixture reset, valuable DB reset or Compiler/Profile/slot/animation/passage change; generic IR/internal fourfile tasks remain distinct from Studio standard Export completion.'})
